#include<bits/stdc++.h>
#define int long long
using namespace std;
vector<int>v[111111];
int c[111111];
bool vis[111111];
int dp[111111];int ans;
void dfs(int p,int f){
//	cout<<p<<endl;
	dp[p]=1;
	vector<int>o;
	for(int i=0;i<v[p].size();i++){
		if(f!=v[p][i]){
			vis[v[p][i]]=1;
			dfs(v[p][i],p);
			dp[p]=max(dp[p],dp[v[p][i]]+1);
			o.push_back(dp[v[p][i]]);
		}
	}
	sort(o.rbegin(),o.rend());
	if(o.size()==1){
		ans=max(ans,o[0]);
	}else if(o.size()>=2){
		ans=max(ans,o[0]+o[1]);
	}
}
signed main(){
    ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n;
	cin>>n;
	for(int i=1;i<=n;i++){
		cin>>c[i];
	}
	for(int i=1;i<n;i++){
		int x,y;
		cin>>x>>y;
		if(c[x]!=c[y]){
			v[x].push_back(y);
			v[y].push_back(x);
		}
	}
	for(int i=1;i<=n;i++){
		if(vis[i]==0){
			vis[i]=1;
			dfs(i,-1);
//			cout<<ans<<endl; 
		}
	}
	cout<<ans+1;
    return 0;
}
